:root {
  --bg: #f6f5f2;
  --surface: #ffffff;
  --ink: #1c1a17;
  --muted: #5d5852;
  --line: #e2ded7;
  --accent: #0f766e;
  --accent-soft: #e6f2f0;
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.55 system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

#app {
  max-width: 46rem;
  margin: 0 auto;
  padding: 2rem 1rem 4rem;
  display: grid;
  gap: 1.5rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.9rem;
  letter-spacing: -0.02em;
}

.tagline {
  margin: 0.25rem 0 0;
  color: var(--muted);
}

.note-form,
.search-bar {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 0.75rem;
  padding: 1.25rem;
  display: grid;
  gap: 1rem;
}

.form-heading {
  margin: 0;
  font-size: 1.1rem;
}

.field {
  display: grid;
  gap: 0.35rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input,
textarea {
  font: inherit;
  color: inherit;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--line);
  border-radius: 0.5rem;
  background: #fff;
  width: 100%;
}

textarea {
  resize: vertical;
  min-height: 6rem;
}

input:focus-visible,
textarea:focus-visible,
button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.hint {
  margin: 0;
  font-size: 0.82rem;
  color: var(--muted);
}

.hint code {
  background: var(--accent-soft);
  border-radius: 0.25rem;
  padding: 0 0.25rem;
}

.submit {
  font: inherit;
  font-weight: 600;
  justify-self: start;
  padding: 0.55rem 1.1rem;
  border: 1px solid var(--accent);
  border-radius: 0.5rem;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}

.submit:hover {
  background: #0b5d56;
}

.results-line {
  margin: 0;
  min-height: 1.2rem;
  color: var(--muted);
  font-size: 0.9rem;
}

.results-line:empty {
  min-height: 0;
}

.feed {
  display: grid;
  gap: 1rem;
}

.note {
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 4px solid transparent;
  border-radius: 0.75rem;
  padding: 1rem 1.25rem;
  display: grid;
  gap: 0.5rem;
}

.note[aria-current='true'] {
  border-left-color: var(--accent);
  background: var(--accent-soft);
}

.note-header {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.note-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--line);
  flex: none;
}

.note-heading {
  margin: 0;
  font-size: 1.15rem;
}

.note-title {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  padding: 0;
  text-align: left;
  cursor: pointer;
}

.note-title:hover {
  color: var(--accent);
  text-decoration: underline;
}

.note-body {
  margin: 0;
  overflow-wrap: anywhere;
}

.note-body a {
  color: var(--accent);
}

.note-date {
  color: var(--muted);
  font-size: 0.8rem;
}

.empty {
  margin: 0;
  padding: 1.5rem;
  text-align: center;
  color: var(--muted);
  border: 1px dashed var(--line);
  border-radius: 0.75rem;
}

