import { spawn } from 'node:child_process';
import path from 'node:path';
import { chromium } from '/workspace/benchmark/runs/lanes/lane-1/arm-a-vibe/node_modules/@playwright/test/index.mjs';

const dir = '/workspace/benchmark/runs/lanes/lane-1/arm-a-vibe';
const port = 4899;
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 600));
const base = `http://127.0.0.1:${port}/`;

let pass = 0, fail = 0;
const ok = (name, cond, extra = '') => { cond ? pass++ : fail++; console.log(`${cond ? 'PASS' : 'FAIL'}  ${name}${cond ? '' : '  ' + extra}`); };

const browser = await chromium.launch();
const ctx = await browser.newContext();
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e.message ?? e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));

await page.goto(base, { waitUntil: 'load' });

// --- element contract ---
ok('#note-form has #title/#body/#avatar/submit',
  await page.$('#note-form #title') && await page.$('#note-form #body') &&
  await page.$('#note-form #avatar') && await page.$('#note-form button[type=submit]'));
ok('6 seeded notes', (await page.$$('#feed article.note')).length === 6);
ok('note has data-note-id', (await page.getAttribute('#feed article.note', 'data-note-id')) !== null);
ok('newest first (id 6 on top)', (await page.getAttribute('#feed article.note', 'data-note-id')) === '6');
ok('.note-title/.note-body present',
  await page.$('article.note .note-title') && await page.$('article.note .note-body'));
ok('avatar img only when given', (await page.$$('#feed img.note-avatar')).length === 3,
  String((await page.$$('#feed img.note-avatar')).length));
ok('results-line empty initially', (await page.textContent('#results-line')) === '');

// --- rich text renders ---
const boldHtml = await page.innerHTML('article.note[data-note-id="3"] .note-body');
ok('bold renders as <b>', boldHtml.includes('<b>Café Santiago</b>'), boldHtml);
ok('<br> renders', boldHtml.includes('<br>'), boldHtml);
const linkHref = await page.getAttribute('article.note[data-note-id="4"] .note-body a', 'href');
ok('link is clickable with href', linkHref === 'https://www.livrarialello.pt/', String(linkHref));
const italic = await page.$('article.note[data-note-id="2"] .note-body i');
ok('<i> renders', !!italic);
const bWeight = await page.$eval('article.note[data-note-id="3"] .note-body b',
  (el) => getComputedStyle(el).fontWeight);
ok('bold word displays bold', Number(bWeight) >= 600, bWeight);

// --- search ---
await page.fill('#search', 'douro');
await page.waitForTimeout(120);
ok('search filters (douro -> 2)', (await page.$$('#feed article.note')).length === 2,
  String((await page.$$('#feed article.note')).length));
ok('results line text', (await page.textContent('#results-line')) === 'results for "douro"',
  await page.textContent('#results-line'));
ok('search reflected in fragment', page.url().endsWith('#q=douro'), page.url());
await page.fill('#search', 'PORT');
await page.waitForTimeout(120);
ok('case-insensitive match', (await page.$$('#feed article.note')).length >= 1,
  String((await page.$$('#feed article.note')).length));
await page.fill('#search', '');
await page.waitForTimeout(120);
ok('cleared search restores feed', (await page.$$('#feed article.note')).length === 6);
ok('cleared search empties results line', (await page.textContent('#results-line')) === '');
ok('cleared search clears fragment', !page.url().includes('#'), page.url());

// --- selection + fragment ---
await page.click('article.note[data-note-id="3"] .note-title');
await page.waitForTimeout(100);
ok('selected note gets aria-current', (await page.getAttribute('article.note[data-note-id="3"]', 'aria-current')) === 'true');
ok('only one selected', (await page.$$('article.note[aria-current="true"]')).length === 1);
ok('fragment #note=3', page.url().endsWith('#note=3'), page.url());
await page.fill('#search', 'port');
await page.waitForTimeout(120);
ok('combined fragment #q=port&note=3', page.url().endsWith('#q=port&note=3'), page.url());

// --- deep link restore on reload ---
await page.goto(base + '#q=port&note=3', { waitUntil: 'load' });
await page.waitForTimeout(200);
ok('deep link restores query', (await page.inputValue('#search')) === 'port');
ok('deep link restores results line', (await page.textContent('#results-line')) === 'results for "port"');
ok('deep link restores selection',
  (await page.getAttribute('article.note[data-note-id="3"]', 'aria-current')) === 'true');
ok('deep link keeps fragment', page.url().endsWith('#q=port&note=3'), page.url());

// --- add a note ---
await page.goto(base, { waitUntil: 'load' });
await page.fill('#title', 'Ponte Luís I');
await page.fill('#body', 'Cross on the <b>top deck</b>.\nGreat view of the <i>Douro</i>.');
await page.fill('#avatar', 'https://example.com/a.png');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(150);
ok('note added at top', (await page.getAttribute('#feed article.note', 'data-note-id')) === '7', page.url());
ok('7 notes now', (await page.$$('#feed article.note')).length === 7);
ok('new note title', (await page.textContent('#feed article.note .note-title')) === 'Ponte Luís I');
const newBody = await page.innerHTML('#feed article.note .note-body');
ok('new note bold + newline->br', newBody.includes('<b>top deck</b>') && newBody.includes('<br>'), newBody);
ok('new note avatar', (await page.getAttribute('#feed article.note img.note-avatar', 'src')) === 'https://example.com/a.png');
ok('form cleared', (await page.inputValue('#title')) === '' && (await page.inputValue('#body')) === '' && (await page.inputValue('#avatar')) === '');

// --- persistence ---
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(200);
ok('persists across reload', (await page.$$('#feed article.note')).length === 7);
ok('persisted note content', (await page.textContent('#feed article.note .note-title')) === 'Ponte Luís I');
await page.fill('#search', 'top deck');
await page.waitForTimeout(120);
ok('new note searchable by body text', (await page.$$('#feed article.note')).length === 1,
  String((await page.$$('#feed article.note')).length));
await page.fill('#search', '');

// --- untrusted markup is shown, not executed ---
const alerts = [];
page.on('dialog', async (d) => { alerts.push(d.message()); await d.dismiss(); });
const attacks = [
  ['<img src=x onerror="window.__x=1">', 'img'],
  ['<script>window.__x=1<\/script>', 'script'],
  ['<b onmouseover="window.__x=1">hi</b>', 'onmouseover-stripped'],
  ['<a href="javascript:window.__x=1">click</a>', 'js-url'],
  ['<iframe src="javascript:window.__x=1"></iframe>', 'iframe'],
  ['<svg onload="window.__x=1"></svg>', 'svg'],
];
for (const [payload, label] of attacks) {
  await page.fill('#title', 'atk ' + label);
  await page.fill('#body', payload);
  await page.click('#note-form button[type=submit]');
  await page.waitForTimeout(80);
}
await page.waitForTimeout(300);
const injected = await page.evaluate(() => ({
  x: window.__x ?? null,
  scripts: document.querySelectorAll('#feed script, #feed iframe, #feed svg, #feed img:not(.note-avatar)').length,
  handlers: document.querySelectorAll('#feed [onerror], #feed [onmouseover], #feed [onload]').length,
  jsHrefs: Array.from(document.querySelectorAll('#feed a')).filter((a) => (a.getAttribute('href') ?? '').toLowerCase().startsWith('javascript:')).length,
}));
ok('no script executed', injected.x === null, JSON.stringify(injected));
ok('no injected elements', injected.scripts === 0, JSON.stringify(injected));
ok('no event-handler attributes', injected.handlers === 0, JSON.stringify(injected));
ok('no javascript: hrefs', injected.jsHrefs === 0, JSON.stringify(injected));
ok('no dialogs', alerts.length === 0, JSON.stringify(alerts));
const literal = await page.textContent('#feed article.note .note-body');
ok('unknown markup shown literally', literal.includes('<svg'), literal);

// --- avatar url is not a script sink ---
