import { chromium } from '@playwright/test';
const browser = await chromium.launch();
const page = await browser.newPage();
const errors = [];
page.on('pageerror', e => errors.push(String(e)));
page.on('console', m => m.type() === 'error' && errors.push(m.text()));

await page.goto('http://127.0.0.1:4599/');
await page.waitForTimeout(300);

const bodyHtml = await page.$eval('article.note[data-note-id="1"] .note-body', el => el.innerHTML);
console.log('note1 body html:', bodyHtml);

const linkHref = await page.$eval('article.note[data-note-id="4"] .note-body a', el => el.getAttribute('href')).catch(()=>null);
console.log('note4 link href:', linkHref);

await page.fill('#search', 'douro');
await page.waitForTimeout(200);
const resultsLine = await page.$eval('#results-line', el => el.textContent);
console.log('results line:', JSON.stringify(resultsLine));
const visibleCount = (await page.$$('article.note')).length;
console.log('visible after search:', visibleCount);
const hash1 = await page.evaluate(() => location.hash);
console.log('hash after search:', hash1);

await page.click('article.note .note-title');
await page.waitForTimeout(200);
const hash2 = await page.evaluate(() => location.hash);
console.log('hash after select:', hash2);
const ariaCurrent = await page.$$eval('article.note[aria-current="true"]', els => els.map(e => e.dataset.noteId));
console.log('aria-current notes:', ariaCurrent);

await page.reload();
await page.waitForTimeout(300);
const searchVal = await page.$eval('#search', el => el.value);
console.log('search value after reload:', searchVal);
const ariaCurrent2 = await page.$$eval('article.note[aria-current="true"]', els => els.map(e => e.dataset.noteId));
console.log('aria-current after reload:', ariaCurrent2);
const resultsLine2 = await page.$eval('#results-line', el => el.textContent);
console.log('results line after reload:', JSON.stringify(resultsLine2));

await page.evaluate(() => { location.hash = ''; });
await page.reload();
await page.waitForTimeout(200);
await page.fill('#title', 'XSS test');
const payload = 'hello <img src=x onerror="window.__xss=true"> <b>bold</b> <a href="javascript:window.__xss3=true">bad link</a> world';
await page.fill('#body', payload);
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(200);
const xss = await page.evaluate(() => window.__xss);
const newNoteBody = await page.$eval('article.note .note-body', el => el.innerHTML);
console.log('xss triggered:', xss);
console.log('new note body (should be first, newest):', newNoteBody);

console.log('errors:', errors);
await browser.close();

