import { spawn } from 'node:child_process';
import path from 'node:path';
import { chromium } from '/workspace/benchmark/runs/lanes/lane-1/arm-a-vibe/node_modules/@playwright/test/index.mjs';

const dir = '/workspace/benchmark/runs/lanes/lane-1/arm-a-vibe';
const port = 4899;
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 600));
const base = `http://127.0.0.1:${port}/`;

let pass = 0, fail = 0;
const ok = (name, cond, extra = '') => { cond ? pass++ : fail++; console.log(`${cond ? 'PASS' : 'FAIL'}  ${name}${cond ? '' : '  >> ' + extra}`); };
const count = async (page, sel) => (await page.$$(sel)).length;

const browser = await chromium.launch();
const page = await browser.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e.message ?? e)));
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
const dialogs = [];
page.on('dialog', async (d) => { dialogs.push(d.message()); await d.dismiss(); });

await page.goto(base, { waitUntil: 'load' });

ok('form has #title/#body/#avatar/submit',
  !!(await page.$('#note-form #title')) && !!(await page.$('#note-form #body')) &&
  !!(await page.$('#note-form #avatar')) && !!(await page.$('#note-form button[type=submit]')));
ok('6 seeded notes', await count(page, '#feed article.note') === 6);
ok('newest first (id 6 top)', (await page.getAttribute('#feed article.note', 'data-note-id')) === '6');
ok('.note-title/.note-body present',
  !!(await page.$('article.note .note-title')) && !!(await page.$('article.note .note-body')));
ok('avatar img only when given', await count(page, '#feed img.note-avatar') === 3,
  String(await count(page, '#feed img.note-avatar')));
ok('results-line empty initially', (await page.textContent('#results-line')) === '');

const b3 = await page.innerHTML('article.note[data-note-id="3"] .note-body');
ok('bold renders as <b>', b3.includes('<b>Café Santiago</b>'), b3);
ok('<br> renders', b3.includes('<br>'), b3);
ok('bold displays bold',
  Number(await page.$eval('article.note[data-note-id="3"] .note-body b', (el) => getComputedStyle(el).fontWeight)) >= 600);
ok('<i> renders', !!(await page.$('article.note[data-note-id="2"] .note-body i')));
ok('link clickable with href',
  (await page.getAttribute('article.note[data-note-id="4"] .note-body a', 'href')) === 'https://www.livrarialello.pt/',
  String(await page.getAttribute('article.note[data-note-id="4"] .note-body a', 'href')));
ok('title renders formatting too',
  (await page.textContent('article.note[data-note-id="1"] .note-title')).includes('Welcome to Porto Notes'));

await page.fill('#search', 'douro');
await page.waitForTimeout(120);
ok('search filters (douro -> 2)', await count(page, '#feed article.note') === 2, String(await count(page, '#feed article.note')));
ok('results line text', (await page.textContent('#results-line')) === 'results for "douro"', await page.textContent('#results-line'));
ok('search in fragment', page.url().endsWith('#q=douro'), page.url());
await page.fill('#search', 'PORT');
await page.waitForTimeout(120);
ok('case-insensitive', await count(page, '#feed article.note') >= 1, String(await count(page, '#feed article.note')));
await page.fill('#search', '');
await page.waitForTimeout(120);
ok('clearing restores feed', await count(page, '#feed article.note') === 6);
ok('clearing empties results line', (await page.textContent('#results-line')) === '');
ok('clearing clears fragment', !page.url().includes('#'), page.url());

await page.click('article.note[data-note-id="3"] .note-title');
await page.waitForTimeout(100);
ok('selected gets aria-current', (await page.getAttribute('article.note[data-note-id="3"]', 'aria-current')) === 'true');
ok('exactly one selected', await count(page, 'article.note[aria-current="true"]') === 1);
ok('fragment #note=3', page.url().endsWith('#note=3'), page.url());
await page.fill('#search', 'port');
await page.waitForTimeout(120);
ok('combined #q=port&note=3', page.url().endsWith('#q=port&note=3'), page.url());

await page.goto(base + '#q=port&note=3', { waitUntil: 'load' });
await page.waitForTimeout(200);
ok('deep link restores query', (await page.inputValue('#search')) === 'port');
ok('deep link restores results line', (await page.textContent('#results-line')) === 'results for "port"');
ok('deep link restores selection', (await page.getAttribute('article.note[data-note-id="3"]', 'aria-current')) === 'true');
ok('deep link keeps fragment', page.url().endsWith('#q=port&note=3'), page.url());

await page.goto(base, { waitUntil: 'load' });
await page.fill('#title', 'Ponte Luis I');
await page.fill('#body', 'Cross on the <b>top deck</b>.\nGreat view of the <i>Douro</i>.');
await page.fill('#avatar', 'https://example.com/a.png');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(150);
ok('new id continues sequence', (await page.getAttribute('#feed article.note', 'data-note-id')) === '7',
  String(await page.getAttribute('#feed article.note', 'data-note-id')));
ok('7 notes now', await count(page, '#feed article.note') === 7);
ok('new note title', (await page.textContent('#feed article.note .note-title')) === 'Ponte Luis I');
const nb = await page.innerHTML('#feed article.note .note-body');
ok('new note bold + newline->br', nb.includes('<b>top deck</b>') && nb.includes('<br>'), nb);
ok('new note avatar', (await page.getAttribute('#feed article.note img.note-avatar', 'src')) === 'https://example.com/a.png');
ok('form cleared', (await page.inputValue('#title')) === '' && (await page.inputValue('#body')) === '' && (await page.inputValue('#avatar')) === '');

await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(200);
ok('persists across reload', await count(page, '#feed article.note') === 7);
ok('persisted content', (await page.textContent('#feed article.note .note-title')) === 'Ponte Luis I');
await page.fill('#search', 'top deck');
await page.waitForTimeout(120);
ok('new note searchable by body', await count(page, '#feed article.note') === 1, String(await count(page, '#feed article.note')));
await page.fill('#search', '');
await page.waitForTimeout(100);

const attacks = [
  '<img src=x onerror="window.__x=1">',
  '<sc' + 'ript>window.__x=1</sc' + 'ript>',
  '<b onmouseover="window.__x=1">hi</b>',
  '<a href="javascript:window.__x=1">click</a>',
  '<a href="JaVaScRiPt:window.__x=1">click</a>',
  '<a href="java\tscript:window.__x=1">click</a>',
  '<iframe src="javascript:window.__x=1"></iframe>',
  '<svg onload="window.__x=1"></svg>',
  '<img src=x onerror=alert(1)>',
];
for (const payload of attacks) {
  await page.fill('#title', 'atk');
  await page.fill('#body', payload);
  await page.click('#note-form button[type=submit]');
  await page.waitForTimeout(80);
}
await page.waitForTimeout(400);
const inj = await page.evaluate(() => ({
  x: window.__x ?? null,
  els: document.querySelectorAll('#feed script, #feed iframe, #feed svg, #feed img:not(.note-avatar)').length,
  handlers: document.querySelectorAll('#feed [onerror], #feed [onmouseover], #feed [onload]').length,
  jsHrefs: Array.from(document.querySelectorAll('#feed a')).filter((a) => (a.getAttribute('href') ?? '').replace(/[�- ]/g, '').toLowerCase().startsWith('javascript:')).length,
}));
ok('no script executed', inj.x === null, JSON.stringify(inj));
ok('no injected elements', inj.els === 0, JSON.stringify(inj));
ok('no handler attributes', inj.handlers === 0, JSON.stringify(inj));
ok('no javascript: hrefs', inj.jsHrefs === 0, JSON.stringify(inj));
ok('no dialogs', dialogs.length === 0, JSON.stringify(dialogs));
ok('unknown markup shown literally', (await page.textContent('#feed article.note .note-body')).includes('<img'),
  await page.textContent('#feed article.note .note-body'));

await page.fill('#title', 'atk avatar');
await page.fill('#body', 'x');
await page.fill('#avatar', 'javascript:window.__y=1');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(200);
ok('javascript: avatar dropped',
  (await page.$eval('#feed article.note', (el) => el.querySelector('img.note-avatar')?.getAttribute('src') ?? null)) === null);
ok('no avatar injection', (await page.evaluate(() => window.__y ?? null)) === null);

ok('no console/page errors', errors.length === 0, errors.join(' | '));

console.log(`\n${pass} passed, ${fail} failed`);
await browser.close();
server.kill();
process.exit(fail ? 1 : 0);

